import { Auth } from "../route/auth.js";
import { AuthOptions } from "../route/auth-options.js";
import { MediaRoute } from "../route/media.js";
import { ProviderID } from "../schema/index.js";
import { Gemini } from "../protocols/gemini.js";
import { GoogleEmbedContent, } from "../protocols/google-embed-content.js";
import { GoogleDecisions } from "../protocols/google-decisions.js";
import { GoogleInteractions } from "../protocols/google-interactions.js";
import { GoogleInteractionsVideo } from "../protocols/google-interactions-video.js";
import { GoogleImages } from "../protocols/google-images.js";
import { GoogleSpeech } from "../protocols/google-speech.js";
import { GoogleTranscription } from "../protocols/google-transcription.js";
import { toConfig } from "./settings.js";
export const id = ProviderID.make("google");
export const routes = [Gemini.route, GoogleInteractions.route];
const auth = (options) => AuthOptions.apiKey(options, "GOOGLE_GENERATIVE_AI_API_KEY", Auth.header("x-goog-api-key"));
const configuredRoute = (input) => {
    const { apiKey: _, auth: _auth, baseURL, ...rest } = input;
    return Gemini.route.with({ ...rest, endpoint: { baseURL }, auth: auth(input) });
};
const interactionsRoute = (input) => {
    const { apiKey: _, auth: _auth, baseURL, ...rest } = input;
    return GoogleInteractions.route.with({ ...rest, endpoint: { baseURL }, auth: auth(input) });
};
export const configure = (input = {}) => {
    const route = configuredRoute(input);
    const media = MediaRoute.deployment(input, auth(input));
    const gemini = (modelID) => route.model({ id: modelID });
    const embeddingRoute = GoogleEmbedContent.route.with({
        provider: id,
        endpoint: { baseURL: input.baseURL },
        auth: auth(input),
        headers: input.headers,
        http: input.http,
    });
    return {
        id,
        model: gemini,
        gemini,
        interactions: (modelID) => interactionsRoute(input).model({ id: modelID }),
        image: (modelID, providerOptions) => GoogleImages.model({ ...media, id: modelID, providerOptions }),
        video: (modelID) => GoogleInteractionsVideo.model({ ...media, id: modelID }),
        speech: (modelID) => GoogleSpeech.model({ ...media, id: modelID }),
        transcription: (modelID) => GoogleTranscription.model({ ...media, id: modelID }),
        embedding: (modelID, providerOptions) => embeddingRoute.model({ id: modelID, providerOptions }),
        decision: (modelID, providerOptions) => GoogleDecisions.route
            .with({ endpoint: { baseURL: media.baseURL }, auth: media.auth, headers: media.headers, http: media.http })
            .model({ id: modelID, providerOptions }),
        configure,
    };
};
export const provider = configure();
export const model = (modelID, settings) => configure(toConfig(settings)).model(modelID);
export const imageModel = (modelID, settings) => {
    const input = toConfig(settings);
    return configure(input).image(modelID, input.providerOptions);
};
export const videoModel = (modelID, settings) => configure(toConfig(settings)).video(modelID);
export const embeddingModel = (modelID, settings) => {
    const input = toConfig(settings);
    return configure(input).embedding(modelID, input.providerOptions);
};
export const decisionModel = (modelID, settings) => {
    const input = toConfig(settings);
    return configure(input).decision(modelID, input.providerOptions);
};
export const image = provider.image;
export const video = provider.video;
export const embedding = provider.embedding;
export const gemini = provider.gemini;
export const interactions = provider.interactions;
export const speech = provider.speech;
export const transcription = provider.transcription;
export const decision = provider.decision;
